extern void** const GOT_TABLE;

// X address stored at a fixed offset (0x10) relative to GOT base
const size_t X_OFFSET = 0x10 / sizeof(void*); 

// Data access (requires two levels of indirection):
// 1. Get the address of X stored in the GOT (Run-time resolved)
int* ptr_to_X = (int*) GOT_TABLE[X_OFFSET];

// 2. Use the dynamically resolved address
*ptr_to_X = 42; 

// Function pointer resolution via PLT/GOT for late binding
typedef int (*Func_T)(void);
Func_T F_ptr = (Func_T) GOT_TABLE[0x20 / sizeof(void*)]; 

F_ptr(); // Call dynamically resolved function F
// Note: GOT must be PC-relative to maintain position independence.
